#set willingness to pay threshold 
wtp <- 500 

#Output folder
msa_dir <- file.path(out_dir, "multivariate_sa")
if (!dir.exists(msa_dir)) dir.create(msa_dir, recursive = TRUE)

# 1. PREPARE DATA
data_all <- data

## 2. AGGREGATE OUTCOMEs FOR ONE PARAMETER SET
#Runs model for every parameter combination
run_agg <- function(p, data, use_planning = FALSE, use_programme = FALSE,
                    plan_mult = 1, prog_mult = 1) {
    epi  <- f_epi(data, p)
    ae   <- f_AE(data, p)
    sae  <- f_SAE(data, p)
    plan_c <- if (use_planning)  plan_mult * data$planning_cost  else 0 #if planning and programme costs are included use multiplier
    prog_c <- if (use_programme) prog_mult * data$programme_cost else 0
    cost <- f_cost(epi, ae, sae, data, p, planning_cost = plan_c, programme_cost = prog_c)
    nd <- sum(cost$net_dalys, na.rm = TRUE) #Sum all across regions
    nc <- sum(cost$net_cost,  na.rm = TRUE)
    c(net_dalys = nd, net_cost = nc, nmb = wtp * nd - nc) #Calculate NMB
}

#Creates every parameter combination, so it has 729 runs, generates all combinations first then runs the model for each combination
run_scenario <- function(levels_list, use_planning, use_programme,    #parameters you want to vary and "fixed"
                         plan_mult = 1, prog_mult = 1, fixed = list()) {
    grid <- expand.grid(levels_list, KEEP.OUT.ATTRS = FALSE) #Makes grid of all combinations of parameters
    outs <- do.call(rbind, lapply(seq_len(nrow(grid)), function(i) { #loops through every combination (row of combinations)
        row <- as.list(grid[i, , drop = FALSE])
        # if plan_mult / prog_mult are swept in the grid, read them per row;
        # otherwise fall back to the fixed scalar for this scenario
        pm <- if (!is.null(row$plan_mult)) row$plan_mult else plan_mult #will vary later when scenarios are defined
        gm <- if (!is.null(row$prog_mult)) row$prog_mult else prog_mult
        # model parameters = grid row MINUS the cost multipliers, plus `fixed`
        ov <- c(row[setdiff(names(row), c("plan_mult", "prog_mult"))], fixed)
        run_agg(make_params(ov), data_all, use_planning, use_programme, pm, gm) #creates parameter object, starts from baseline parameters and replaces only those in ov
    }))
    cbind(grid, outs) #attach parameter combinations to outputs 
}



## 3. PARAMETER GRID  (single global factorial)
scenarios <- list(
    global = list(
        levels = list(IDE          = c(0.00, 0.125, 0.25),   # no benefit -> upper plausible efficacy
                      IAEp         = c(1.00, 1.50,  2.00),   # no extra AE risk -> doubling
                      ISAEp        = c(1.00, 1.50,  2.00),   # no extra SAE risk -> doubling
                      cfr_SAE      = c(0.02, 0.06,  0.10),   # SAE case fatality
                      plan_mult    = c(0.60, 1.05,  1.50),   # planning cost multiplier
                      prog_mult    = c(0.00, 0.75,  1.50),   # programme cost multiplier
                      ivm_cost_400 = c(0.00, 0.20,  0.40)),  # donated -> full procurement cost
        use_planning = TRUE, use_programme = TRUE, fixed = list())
)

# rows shown in the box grid (and their display labels)
param_order  <- c("IDE", "IAEp", "ISAEp", "cfr_SAE", "ivm_cost_400", "plan_mult", "prog_mult")
param_labels <- c(IDE = "IDE", IAEp = "IAEp", ISAEp = "ISAEp", cfr_SAE = "cfr_SAE",
                  ivm_cost_400 = "IVM drug cost",
                  plan_mult = "Planning cost mult.", prog_mult = "Programme cost mult.")

## 4. PLOT  (order of influence across ALL parameters)
# Each box = the distribution of the outcome over all combinations of the OTHER
# parameters, with the row parameter held at the level shown on the vertical axis.
# A parameter is influential where its boxes are DISPLACED relative to one another,
# not where they are wide. vline0 = TRUE adds a reference line at zero.

make_msa_plot <- function(long, valcol, facet_scales, xlab, title, subtitle, vline0 = FALSE) {
    lv_ord <- intersect(param_order, unique(long$parameter))   #order for parameters
    long$parameter <- factor(long$parameter, levels = lv_ord, #Changes parameter names into ordered categories
                             labels = param_labels[lv_ord])
    g <- ggplot(long, aes(x = .data[[valcol]], y = factor(signif(level, 3)), fill = parameter))
    if (vline0) g <- g + geom_vline(xintercept = 0, linetype = "dashed", colour = "grey55")
    g +
        geom_boxplot(outlier.size = 0.2, linewidth = 0.3, alpha = 0.9) +
        facet_grid(parameter ~ ., scales = facet_scales, space = "free_y", switch = "y") +
        scale_fill_brewer(palette = "Set2", guide = "none") +
        labs(title = NULL, subtitle = NULL, x = xlab, y = NULL) +
        theme_bw(base_size = 9) +
        theme(strip.placement = "outside",
              strip.background.y = element_rect(fill = "grey92", colour = NA),
              strip.text.y.left = element_text(angle = 0, face = "bold"),
              panel.spacing = unit(0.3, "lines"))
}

## 4b. COMBINED PLOT  (all three outcomes side by side)
# Same rows as above (one per parameter), but one COLUMN per outcome. The three
# outcomes are on different units, so the x scale is free within each column;
# the shared row structure is what makes them comparable - a parameter that
# displaces the boxes in one column but not another acts on that outcome only.
# Units are carried in the column strip labels rather than the axis title.

make_msa_combined <- function(long, cols, col_labels, vline0 = TRUE) {
    lv_ord <- intersect(param_order, unique(long$parameter))
    d <- long[, c("parameter", "level", cols)]
    d <- pivot_longer(d, cols = -c(parameter, level),
                      names_to = "outcome", values_to = "value")
    d$parameter <- factor(d$parameter, levels = lv_ord, labels = param_labels[lv_ord])
    d$outcome   <- factor(d$outcome,   levels = cols,   labels = col_labels)

    g <- ggplot(d, aes(x = value, y = factor(signif(level, 3)), fill = parameter))
    if (vline0) g <- g + geom_vline(xintercept = 0, linetype = "dashed", colour = "grey55")
    g +
        geom_boxplot(outlier.size = 0.2, linewidth = 0.3, alpha = 0.9) +
        facet_grid(parameter ~ outcome, scales = "free", space = "free_y", switch = "y") +
        scale_fill_brewer(palette = "Set2", guide = "none") +
        labs(x = NULL, y = NULL) +
        theme_bw(base_size = 9) +
        theme(strip.placement    = "outside",
              strip.background   = element_rect(fill = "grey92", colour = NA),
              strip.text.y.left  = element_text(angle = 0, face = "bold"),
              strip.text.x       = element_text(face = "bold"),
              panel.spacing      = unit(0.3, "lines"))
}

## 5. RUN EACH SCENARIO -> SIX FIGURES (raw + % change, each for net DALYs, net cost & NMB)
##    plus TWO COMBINED FIGURES (all three outcomes in one panel, raw and % change)

#Define labs for two types of plots
sub_raw <- "Each box = outcome distribution over all OTHER parameters, with the row parameter held at the level shown"
sub_pct <- "% change from the central base case (all parameters at their middle value)"

#Loop through each scenario
for (sc in names(scenarios)) {
    cfg <- scenarios[[sc]]; lv <- cfg$levels #which multipliers and parameter values to test
    cat("Running", sc, "factorial (", prod(lengths(lv)), "combinations )...\n")
    res <- run_scenario(lv, cfg$use_planning, cfg$use_programme, #calls earlier function (create every possible combination, run the model for each combination and produce output)
                        cfg$plan_mult, cfg$prog_mult, cfg$fixed)

    # SINGLE central base case: every parameter at its middle value.
    base_all <- lapply(lv, function(v) v[ceiling(length(v) / 2)])
    pm_base  <- if (!is.null(base_all$plan_mult)) base_all$plan_mult else cfg$plan_mult
    gm_base  <- if (!is.null(base_all$prog_mult)) base_all$prog_mult else cfg$prog_mult
    base_p   <- base_all[setdiff(names(base_all), c("plan_mult", "prog_mult"))]
    o_base   <- run_agg(make_params(c(base_p, cfg$fixed)), data_all,
                        cfg$use_planning, cfg$use_programme, pm_base, gm_base)
    base_dalys <- unname(o_base["net_dalys"])
    base_cost  <- unname(o_base["net_cost"])
    base_nmb   <- unname(o_base["nmb"])
    cat("  base case: net DALYs", round(base_dalys), "| net cost", round(base_cost),
        "| NMB", round(base_nmb), "\n")

    # Convert results into long format
    long <- as.data.frame(res) %>%
        pivot_longer(cols = -c(net_dalys, net_cost, nmb), names_to = "parameter", values_to = "level") %>%
        mutate(dalys_M   = net_dalys / 1e6, #convert to millions
               cost_M    = net_cost / 1e6,
               nmb_bn    = nmb / 1e9, #convert to billions
               pct_dalys = (net_dalys - base_dalys) / abs(base_dalys) * 100,
               pct_cost  = (net_cost  - base_cost)  / abs(base_cost)  * 100,
               pct_nmb   = (nmb       - base_nmb)   / abs(base_nmb)   * 100)

    long_pct <- long  

    n_rows <- length(unique(long$parameter)); h <- 1.2 + 1.15 * n_rows
    scn <- tools::toTitleCase(sc)

    # RAW 
    ggsave(file.path(msa_dir, paste0(sc, "_raw_netdalys.png")),
           make_msa_plot(long, "dalys_M", "free", "Net DALYs averted (millions)", #valcol is second argument
                         paste0(scn, " — net DALYs by parameter level (raw)"), sub_raw, vline0 = TRUE),
           width = 10, height = h, dpi = 300)
    ggsave(file.path(msa_dir, paste0(sc, "_raw_nmb.png")),
           make_msa_plot(long, "nmb_bn", "free", "Net monetary benefit (US$ billions)",
                         paste0(scn, " — NMB by parameter level (raw)"), sub_raw, vline0 = TRUE),
           width = 10, height = h, dpi = 300)
    ggsave(file.path(msa_dir, paste0(sc, "_raw_netcost.png")),
           make_msa_plot(long, "cost_M", "free", "Net cost (US$ millions)",
                         paste0(scn, " — net cost by parameter level (raw)"), sub_raw, vline0 = TRUE),
           width = 10, height = h, dpi = 300)

    # RELATIVE (% change; x shared so columns are comparable) 
    ggsave(file.path(msa_dir, paste0(sc, "_pct_netdalys.png")),
           make_msa_plot(long_pct, "pct_dalys", "free_y", "% change in net DALYs from baseline",
                         paste0(scn, " — net DALYs, % change (conditional importance)"), sub_pct, vline0 = TRUE),
           width = 9, height = h, dpi = 300)
    ggsave(file.path(msa_dir, paste0(sc, "_pct_nmb.png")),
           make_msa_plot(long_pct, "pct_nmb", "free_y", "% change in NMB from baseline",
                         paste0(scn, " — NMB, % change (conditional importance)"), sub_pct, vline0 = TRUE),
           width = 9, height = h, dpi = 300)
    ggsave(file.path(msa_dir, paste0(sc, "_pct_netcost.png")),
           make_msa_plot(long_pct, "pct_cost", "free_y", "% change in net cost from baseline",
                         paste0(scn, " — net cost, % change (conditional importance)"), sub_pct, vline0 = TRUE),
           width = 9, height = h, dpi = 300)
    # COMBINED: all three outcomes in one figure (raw, then % change)
    ggsave(file.path(msa_dir, paste0(sc, "_raw_all_outcomes.png")),
           make_msa_combined(long, c("dalys_M", "cost_M", "nmb_bn"),
                             c("Net DALYs averted (millions)",
                               "Net cost (US$ millions)",
                               "Net monetary benefit (US$ billions)")),
           width = 14, height = h, dpi = 300)
    ggsave(file.path(msa_dir, paste0(sc, "_pct_all_outcomes.png")),
           make_msa_combined(long_pct, c("pct_dalys", "pct_cost", "pct_nmb"),
                             c("% change in net DALYs",
                               "% change in net cost",
                               "% change in NMB")),
           width = 14, height = h, dpi = 300)

    write.csv(as.data.frame(res), file.path(msa_dir, paste0(sc, "_factorial_results.csv")),
              row.names = FALSE)
    cat("  saved 8 figures + factorial results for", sc, "\n")
}
cat("Done. 8 figures in", msa_dir, "\n")

